import Files from 'src/client/files.js';

// #UserData
this.componentData = await Files.fileTree("src/components");

// #UserData -> #Visualization
const weight = "size";
const height = "size";
const color = "size";
const label = "name";

this.setData({
    data: this.componentData,
    weightAttributeName: weight,
    heightAttributeName: height,
    colorAttributeName: color,
    labelAttributeName: label
});

this.removeHighlights()
this.showLabels(['lively-container.js'])

// Change basePath if hosted locally
const basePath = 'https://lively-kernel.org/lively4/lively4-treemap/src/components/';
this.setNodeSelectFunction(
  event => {
    let nodeID = event.node;
    let nodePath = ""
    let currentNodeID = nodeID;
    while (this.getParentID(currentNodeID) !== undefined) {
      if(this.getLabel(currentNodeID) !== undefined) nodePath = this.getLabel(currentNodeID) + "/" +  nodePath;
      currentNodeID = this.getParentID(currentNodeID);
    }
    lively.openBrowser(basePath + nodePath);
  }
);
